#!/usr/bin/env node
// Renders docs/benchmarks.md from bench/results/latest.json (and optional bench/results/triage.json).
// Every number in the document comes from the results file. Do not edit the output by hand.
//   node bench/render.mjs [results.json] [triage.json] > docs/benchmarks.md
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const resultsPath = resolve(process.argv[2] ?? join(here, "results/latest.json"));
const triagePath = resolve(process.argv[3] ?? join(here, "results/triage.json"));
const R = JSON.parse(readFileSync(resultsPath, "utf8"));
const T = existsSync(triagePath) ? JSON.parse(readFileSync(triagePath, "utf8")) : null;

const s = (ms) => `${(ms / 1000).toFixed(1)} s`;
const range = (st) => `${s(st.median)} (${s(st.min)}–${s(st.max)})`;
const ratio = (a, b) => (a && b ? `${(a / b).toFixed(2)}×` : "n/a");
const rows = Object.entries(R.repos);
const L = [];
const p = (x = "") => L.push(x);

p("# Benchmarks");
p();
p(
  "> Generated by `node bench/render.mjs` from `bench/results/latest.json`. Do not edit by hand; re-run `node bench/run.mjs` to reproduce.",
);
p();
p("## Setup");
p();
p(
  `- Machine: ${R.machine.cpuModel}, ${R.machine.cpus} logical CPUs, ${R.machine.memGB} GB RAM, ${R.machine.os}; Node ${R.node}.`,
);
p(
  `- Engines: gitleaks ${R.tools.gitleaks}; semgrep ${R.tools.semgrep}; ${R.tools["osv-scanner"].replace("osv-scanner version: ", "osv-scanner ")}. Semgrep uses the registry ruleset \`p/default\`.`,
);
p(
  `- ${R.runsPerScenario} runs per scenario, reported as median (min–max). The "existing workflow" and \`code-intel\` full scans are **interleaved** run by run, so slow drift (network, thermal) affects both sides alike.`,
);
p(
  "- Load average (1 min) when each repository started: " +
    rows.map(([n, r]) => `${n} ${r.loadAvg1mAtStart}`).join(", ") +
    ".",
);
p();
p(
  "**Caveats, stated plainly.** This is a single developer workstation that was running other work during the measurements (see load averages), so absolute times are indicative and not a guarantee for your machine. `osv-scanner` queries a remote API and its time varies run to run. Peak RSS is the largest single process reported by `/usr/bin/time`, not the sum of the tree. No baseline for an LLM-only review was measured: it is not comparable and is not claimed.",
);
p();
p("## What is compared");
p();
p(
  "- **Existing workflow**: run `gitleaks dir .`, `semgrep scan --config p/default .` and `osv-scanner scan source -r .` by hand, one after another, over the whole repository.",
);
p(
  "- **code-intel full**: `code-intel scan --all --no-cache` (quick profile) on the same repository: the same three engines, run concurrently, with normalization.",
);
p(
  "- **code-intel incremental**: change one source file, run `code-intel scan --no-cache` (changed files only).",
);
p();
p("## Full scan: existing workflow vs code-intel");
p();
p(
  "| Repository | Files | Existing workflow (sequential) | code-intel full | code-intel / existing | Peak RSS (code-intel) | Peak RSS (manual semgrep) |",
);
p("|---|---:|---:|---:|---:|---:|---:|");
for (const [n, r] of rows) {
  const m = r.manualSequentialFullScan;
  const c = r.codeIntelFullCold;
  p(
    `| ${n} (${r.kind}) | ${r.trackedFiles} | ${range(m.wallMs)} | ${range(c.wallMs)} | ${ratio(c.wallMs.median, m.wallMs.median)} | ${c.peakRssMb ?? "n/a"} MB | ${m.peakRssMb.semgrep ?? "n/a"} MB |`,
  );
}
p();
p(
  "A ratio below 1.00× means `code-intel` was faster. Where semgrep dominates the runtime (large repositories), concurrency cannot help and the two are expected to be roughly equal; the gain appears where several engines each take real time.",
);
p();
p("### Where the time goes (median per engine, ms)");
p();
p(
  "| Repository | gitleaks (manual / code-intel) | semgrep (manual / code-intel) | osv-scanner (manual / code-intel) | Σ engine time vs wall |",
);
p("|---|---:|---:|---:|---:|");
for (const [n, r] of rows) {
  const m = r.manualSequentialFullScan.perToolMedianMs;
  const e = r.codeIntelFullCold.engines;
  const f = (k) => `${m[k]} / ${e[k]?.ms ?? "n/a"}`;
  p(
    `| ${n} | ${f("gitleaks")} | ${f("semgrep")} | ${f("osv-scanner")} | ${r.codeIntelFullCold.sumEngineMs} ms Σ vs ${r.codeIntelFullCold.wallMs.median} ms wall |`,
  );
}
p();
p("## Incremental vs full");
p();
p("| Repository | code-intel full | code-intel, 1 file changed | Speed-up |");
p("|---|---:|---:|---:|");
for (const [n, r] of rows) {
  const i = r.codeIntelIncrementalOneFile;
  if (i)
    p(
      `| ${n} | ${range(r.codeIntelFullCold.wallMs)} | ${range(i.wallMs)} | ${ratio(r.codeIntelFullCold.wallMs.median, i.wallMs.median)} |`,
    );
}
p();
p(
  "Semgrep's fixed start-up cost (a couple of seconds) is paid on every invocation, which is why incremental scans of small repositories are not much faster than full ones. The benefit grows with repository size.",
);
p();
p("## Result cache");
p();
p("| Repository | Cold (no cache) | Warm (second run) | Engines served from cache |");
p("|---|---:|---:|---|");
for (const [n, r] of rows) {
  const cached = Object.entries(r.codeIntelFullWarm.engines)
    .filter(([, e]) => e.cached)
    .map(([k]) => k);
  p(
    `| ${n} | ${range(r.codeIntelFullCold.wallMs)} | ${range(r.codeIntelFullWarm.wallMs)} | ${cached.length ? cached.join(", ") : "none"} |`,
  );
}
p();
p(
  "Only engines whose output is a pure function of the file contents are cacheable (gitleaks; semgrep with local rules). Dependency scanners depend on a changing vulnerability database and semgrep registry rules change remotely, so they are never cached. With the default configuration the cache therefore saves only the (small) gitleaks time. This is by design, not a measurement shortfall.",
);
p();
p("## Findings");
p();
p(
  "| Repository | gitleaks raw → code-intel | semgrep raw → code-intel | osv-scanner raw (advisory groups) → code-intel | Severity breakdown (code-intel) |",
);
p("|---|---|---|---|---|");
for (const [n, r] of rows) {
  const raw = r.manualSequentialFullScan.findings;
  const e = r.codeIntelFullCold.engines;
  const sev =
    Object.entries(r.codeIntelFullCold.bySeverity)
      .filter(([, v]) => v > 0)
      .map(([k, v]) => `${v} ${k}`)
      .join(", ") || "none";
  p(
    `| ${n} | ${raw.gitleaks} → ${e.gitleaks?.findings ?? "n/a"} | ${raw.semgrep} → ${e.semgrep?.findings ?? "n/a"} | ${raw["osv-scanner"]} → ${e["osv-scanner"]?.findings ?? "n/a"} | ${sev} |`,
  );
}
p();
p(
  '"raw" is what the tool prints when run by hand; "code-intel" is after normalization (the same issue reported by two engines becomes one finding, and `--exclude` globs such as `dist/` and `vendor/` apply). Small differences are expected and explained by those two effects.',
);
p();
if (R.defectInjection) {
  const d = R.defectInjection;
  p("## Defect injection");
  p();
  p(
    `Planted ${d.total} defects in a copy of the express repository, then ran \`code-intel scan\` on the change (${s(d.wallMs)}).`,
  );
  p();
  p("| Planted defect | Detected |");
  p("|---|:--:|");
  for (const [k, v] of Object.entries(d.detection)) p(`| ${k} | ${v ? "yes" : "**no**"} |`);
  p();
  p(
    `**${d.detected} of ${d.total} detected.** The misses are limits of the engines' rules, not of the pipeline: raw semgrep reported ${d.rawSemgrepFindingsOnInjectedFiles} findings on exactly those files, and ${d.rawSemgrepFindingsMissingFromCodeIntel.length} of them were missing from the \`code-intel\` output (${d.rawSemgrepFindingsMissingFromCodeIntel.length === 0 ? "none lost" : d.rawSemgrepFindingsMissingFromCodeIntel.join("; ")}). Semgrep's \`p/default\` child-process rule matches some call shapes and not others, which is why the two spellings of the same injection are listed separately. A clean report means "these rules found nothing", never "this code is safe".`,
  );
  p();
}
if (T) {
  p("## Precision (false positives)");
  p();
  p(T.method);
  p();
  p("| Repository | Findings reviewed | Judged real | Judged false / noise | Notes |");
  p("|---|---:|---:|---:|---|");
  for (const x of T.repos)
    p(`| ${x.name} | ${x.reviewed} | ${x.real} | ${x.falsePositive} | ${x.notes} |`);
  p();
  if (T.summary) p(T.summary);
  p();
} else {
  p("## Precision (false positives)");
  p();
  p("Not measured in this run. No triage file was provided, so no false-positive rate is claimed.");
  p();
}
p("## What is not measured");
p();
p("- Windows and Linux timings (all numbers above are from one macOS machine).");
p(
  "- `code-intel mutate` on the corpus repositories: mutation testing needs each project's dependencies installed and a tests-only test command. Its behavior is covered by integration tests instead (`test/integration/mutate.test.ts`), not by timing claims.",
);
p(
  "- Comparison with an LLM-only review. No LLM review was run, so no claim is made about detection versus one.",
);
console.log(L.join("\n"));
